// scripts/rb1r-self-closeout.mjs
//
// RB-1R self-validation closeout — the card's OWN bundle is generated by the
// PRODUCTION Graph closeout hook（runSubagentGraph → runColimaGraph →
// runMandatoryGraphCloseout → runCloseoutGate）, NOT by a hand-written source
// or a manual CLI invocation.
//
// The graph is the REAL review/repair ceremony:
//   SA-R1 ‖ SA-R2 -> SA-W1 -> SA-V1
//   SA-W1 lifecycle: writer (attempt 0) -> INDEPENDENT review agent finds an
//   evidence gap -> REPAIR (attempt 1) -> re-review PASS -> verifier.
// The mandatory closeout hook then auto-generates the RB-1R bundle from the
// structured graph result + git-derived repo identity（package.json intact）.
//
// Run: node scripts/rb1r-self-closeout.mjs

import { homedir } from "node:os";
import { mkdirSync, rmSync } from "node:fs";
import { join } from "node:path";
import { runSubagentGraph } from "../src/subagent/subagent-graph-runner.mjs";

const HOME = homedir();
const REPO_A = "/Volumes/NVM2T/Development/autoloop";
const SCRATCH = `${HOME}/autoloop-rb1r-self-closeout`;
const PROFILE = "autoloop-graph";
const PARENT = { scope: { allowed_paths: ["docs/"], forbidden_paths: [".git"] } };
const SCOPE = "docs/pi-graph-output";
const EXECUTION_ID = "rb1r-self-closeout-20260807";
const OUT = "/Users/zhengfengqing/Desktop/AutoLoop-Review/governance/review-bundle";

const roPhase = (phaseId, taskType) => ({
  phase_id: phaseId,
  depends_on: [],
  effects: { artifact_mutation: "none" },
  runtime: {
    mode: "subagent",
    agentRole: "readonly-analyst",
    taskType,
    objective: `read-only ${taskType} over /src/docs`,
    expect: { stdoutContains: [`SUBAGENT_DONE:${taskType}`] },
    limits: { memoryMiB: 256 },
    sleep: 3,
  },
});

const writerPhase = {
  phase_id: "SA-W1",
  depends_on: ["SA-R1", "SA-R2"],
  effects: { artifact_mutation: "required", boundaries: { artifact: [SCOPE] } },
  runtime: {
    mode: "subagent",
    agentRole: "writer",
    taskType: "write_report_with_gap",
    repairTaskType: "repair_report",
    objective: `writer write_report_with_gap over /work/${SCOPE} using dependency results`,
    expect: { stdoutContains: ["SUBAGENT_DONE:write_report_with_gap"] },
    limits: { memoryMiB: 256 },
  },
};

const verifierPhase = {
  phase_id: "SA-V1",
  depends_on: ["SA-W1"],
  effects: { artifact_mutation: "none" },
  runtime: {
    mode: "subagent",
    agentRole: "verifier",
    taskType: "verify_writer",
    objective: "verify writer SA-W1 diff/tests/scope + independent review from /results artifacts",
    expect: { stdoutContains: ["SUBAGENT_DONE:verify_writer"] },
    limits: { memoryMiB: 256 },
  },
};

const ir = { phases: [roPhase("SA-R1", "count_todos"), roPhase("SA-R2", "inventory_markdown"), writerPhase, verifierPhase] };

const closeout = {
  requiresReview: true,
  outDir: OUT,
  cardId: "AUTOLOOP-PI-GRAPH-RB1R-1",
  cardTitle: "Mandatory Graph Closeout Hook and Repository Path Identity Repair",
  cardType: "repair",
  objective: "RB-1R bounded repair: (1) make runCloseoutGate a MANDATORY, non-bypassable card-level closeout hook in the generic Graph runner (runColimaGraph) so every external-review card auto-generates + validates one review bundle before final PASS; (2) fix the repository path-identity parser that truncated package.json to ackage.json by switching to NUL-delimited git porcelain v1. Self-closeout executed through the production Graph closeout hook (this run) — no manual CLI was the closeout method.",
  authorizedScope: [
    "src/governance/review-bundle.mjs",
    "src/runtime/colima-graph-runner.mjs",
    "src/runtime/colima-worktree.mjs",
    "src/subagent/subagent-graph-runner.mjs",
    "scripts/gov-closeout-bundle.mjs",
    "test/governance/test-review-bundle.mjs",
    "test/governance/test-graph-closeout.mjs",
    "test/governance/test-git-status-parsing.mjs",
    "test/test-graph-closeout-integration.mjs",
    "package.json",
  ],
  unauthorizedScope: [
    "CBM-2 schema or production memory implementation",
    "multi-writer parallel",
    "auto commit/push/merge/seal",
    "external services/network/embedding/vector DB",
    "self-evolution",
    "sub-agent spawning sub-agents",
    "large-scale Graph runner refactor",
    "replacing the review bundle schema",
    "hand-written bundles replacing the formal generator",
  ],
  designDecisions: [
    "runCloseoutGate is the ONE gate (CLI/backfill/Graph all call it); runMandatoryGraphCloseout makes it mandatory at the generic Graph runner's card-level closeout boundary",
    "applicability contract is a STRUCTURED closeout.requiresReview flag — never free-text stdout; node-level interim PASS != card-level final closeout",
    "fail-closed: a PASS graph whose bundle gate fails is downgraded to HOLD (REVIEW_BUNDLE_* hold codes); no downstream PASS without a validated bundle",
    "bundle ordering: final review -> generate -> pre-write secret scan -> atomic write -> independent validation -> verdict (validation never after the verdict)",
    "repo path identity via `git status --porcelain=v1 -z` (NUL-delimited, core.quotepath=false, --untracked-files=all); rename records carry source+destination; malformed records fail closed",
    "same first-character defect class fixed in colima-worktree captureWorktreeOutput (structured NUL-parsed file records)",
    "the closeout evidence snapshot is closeout-layer-written, bounded, secret-scanned, and tool-hashed",
    "one writer: the closeout layer writes evidence + bundle atomically (tmp + rename); no parallel closeout",
  ],
  negativeCases: [
    "generator crash/timeout -> HOLD REVIEW_BUNDLE_GENERATION_FAILED",
    "validator rejection -> HOLD REVIEW_BUNDLE_INVALID",
    "secret injection -> HOLD REVIEW_BUNDLE_SECRET_DETECTED (bundle zero bytes on disk)",
    "wrong HEAD/tree -> HOLD REVIEW_BUNDLE_IDENTITY_MISMATCH",
    "blocking final review -> no PASS",
    "graph PASS + bundle-gate failure -> graph downgraded to HOLD (no downstream)",
    "path parser: package.json never truncated; spaces/Unicode/nested/rename/staged/untracked parsed correctly; NUL boundaries handled; dirty digest deterministic",
    "temp files cleaned on success/failure/timeout/crash",
  ],
  regression: [
    { suite: "npm run check (syntax)", tests: 1, pass: 1, fail: 0 },
    { suite: "test:governance (incl. RB-1 + graph closeout + path parsing)", tests: 198, pass: 198, fail: 0 },
    { suite: "test:scripted-lifecycle", tests: 43, pass: 43, fail: 0 },
    { suite: "test:v2", tests: 357, pass: 357, fail: 0 },
    { suite: "test:c2", tests: 43, pass: 43, fail: 0 },
    { suite: "test:c3", tests: 41, pass: 41, fail: 0 },
    { suite: "test:colima-all (incl. graph-closeout e2e)", tests: 41, pass: 41, fail: 0 },
  ],
  regressionSummary: "At RB-1R closeout time: check OK, governance 198/198, scripted-lifecycle 43/43, v2 357/357, c2 43/43, c3 41/41, colima-all 41/41 — all green.",
  repairBudgetMaxAttempts: 1,
  executiveSummary: "RB-1R complete: mandatory closeout hook wired into the single generic Graph closeout path (runColimaGraph); repo path identity repaired via NUL-delimited porcelain parsing; 26+12+12 focused tests, e2e wiring verified; this bundle auto-generated by the production Graph closeout hook after the independent review agent PASS.",
  recommendedNextStep: "CBM-2 Memory Contract and Schema Definition",
  rollbackProcedure: "Revert RB-1R production edits (review-bundle parser + mandatory hook, colima-graph-runner wiring, colima-worktree capture, subagent-graph-runner forwarding, package.json scripts); pre-repair bundles preserved as evidence.",
  openQuestions: [],
  risks: [],
  limitations: ["cards not marked requiresReview skip the bundle gate (internal nodes keep node-level interim completion only)"],
};

mkdirSync(SCRATCH, { recursive: true });
mkdirSync(OUT, { recursive: true });

const r = await runSubagentGraph({
  ir,
  parent: PARENT,
  cwd: REPO_A,
  executionId: EXECUTION_ID,
  profile: PROFILE,
  repoPath: REPO_A,
  scratchRoot: SCRATCH,
  maxRepairAttempts: 1,
  timeoutMs: 240000,
  closeout,
});

console.log(`graph final=${r.final} reason=${r.reason ?? "null"}`);
console.log(`closeout applied=${r.closeout.applied} final=${r.closeout.final} holdCode=${r.closeout.holdCode ?? "null"}`);
if (r.closeout.reason) console.log(`closeout reason: ${r.closeout.reason}`);
if (r.closeout.bundlePath) {
  console.log(`bundle: ${r.closeout.bundlePath}`);
  console.log(`reviewBundleIdentity: ${r.closeout.bundle.identity}`);
  console.log(`reviewBundleSha256: ${r.closeout.bundle.sha256}`);
}
const w1 = r.nodeResults.find((n) => n.nodeId === "SA-W1");
if (w1) console.log(`W1 attempt=${w1.attempt} review=${w1.reviewResult?.recommendedAction} blocking=${JSON.stringify(w1.reviewResult?.blockingFindings ?? [])}`);

rmSync(SCRATCH, { recursive: true, force: true });
process.exit(r.final === "PASS" && r.closeout.final === "PASS" ? 0 : 1);
